preConditionHook:
// MicroChannelRunLength's all-pairs test read one bar back: the channel had to
// have held over the minBars pairs ENDING AT BAR 1, so the loop runs
// kk = 1 .. minBars and reaches low[minBars + 1].
// Same inclusive containment (only a strictly lower low breaks a bull micro
// channel) and the same EL relational tolerance via el_lt/el_gt.
priorChanLow = true;
priorChanHigh = true;
for (int i = 1; i <= (int)minBars; ++i) {
    if (el_lt(low[i], low[i + 1])) priorChanLow = false;
    if (el_gt(high[i], high[i + 1])) priorChanHigh = false;
}
